import{c as t,Q as o,j as a,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Copilot — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/overview.md","filePath":"copilot/overview.md","lastUpdated":null}'),s={name:"copilot/overview.md"};function i(n,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="copilot-—-overview" tabindex="-1">Copilot — Overview <a class="header-anchor" href="#copilot-—-overview" aria-label="Permalink to &quot;Copilot — Overview&quot;">​</a></h1><p>The Copilot is a conversational, goal-aware planner that reads your actual ledger and turns it into next steps — with figures you can verify and actions you approve.</p><p>It is <strong>not</strong> a generic chatbot. Every answer is grounded in <code>finsight-agent::context::FinancialContext</code> built from your encrypted database at request time: cashflow, budget, goals, transactions in scope, memories, and wellness metrics.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Q&amp;A</strong> — “How much did I spend on dining last month?” — answers with cited totals and the query that produced them.</li><li><strong>Planning</strong> — “Help me save $10k by December.” — drafts a plan whose tool calls you review before they run.</li><li><strong>Nudges</strong> — the Today next-action and anomaly callouts point you to the Copilot with a prefilled, groundsable prompt.</li><li><strong>Scenarios &amp; recipes</strong> — natural language maps to deterministic finance tools; recipes propose multi-step automations you confirm.</li></ul><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><ul><li>Move money, call banks, or execute silently. Every actionable step is shown as a plan and waits for you.</li><li>Invent totals. The system prompt forbids presenting a single-currency subtotal as your whole position when unconverted holdings exist — and the prompt’s currency block will warn the model not to.</li><li>Remember across users. Memories and provider keys are per-user; households share a server but not a database.</li></ul><h2 id="surface" tabindex="-1">Surface <a class="header-anchor" href="#surface" aria-label="Permalink to &quot;Surface&quot;">​</a></h2><p>The Copilot lives at <strong>/copilot</strong>. The composer streams over SSE (<code>GET /api/events</code>), renders streamed reasoning blocks as a collapsible <code>&lt;details&gt;</code>, and surfaces typed generative-UI cards (metrics, charts, tables) via <code>Streamdown</code>.</p><p>Next: <a href="/FinSight/copilot/how-it-works">How the Copilot Works</a>.</p>',10)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
